"use client"

import * as React from "react"

import { Field, FieldDescription, FieldLabel } from "@/components/ui/field"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/components/ui/input-group"
import { Spinner } from "@/components/ui/spinner"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import {
  RESPONSE_MAX_CHARS,
  type PreviewVoice,
} from "@/lib/mockups/phrase-mappings-data"
import { cn } from "@/lib/utils"

import { PlayPreviewIcon, StopPreviewIcon } from "./icons"

const RENDER_MS = 700

const SPEECH_MS_PER_CHAR = 95
const MIN_SPEECH_MS = 1100

type Preview = "idle" | "rendering" | "playing"

export function ResponseField({
  disabled,
  fieldId,
  onChange,
  value,
  voice,
}: {
  disabled: boolean
  fieldId: string
  onChange: (response: string) => void
  value: string
  voice: PreviewVoice
}) {
  const [preview, setPreview] = React.useState<Preview>("idle")

  const overLimit = value.length > RESPONSE_MAX_CHARS
  const spoken = value.trim()

  React.useEffect(() => {
    if (preview === "idle") return

    const timer = window.setTimeout(
      () => setPreview(preview === "rendering" ? "playing" : "idle"),
      preview === "rendering"
        ? RENDER_MS
        : Math.max(MIN_SPEECH_MS, spoken.length * SPEECH_MS_PER_CHAR),
    )

    return () => window.clearTimeout(timer)
  }, [preview, spoken.length])

  const label =
    preview === "idle" ? `Play in ${voice.name}'s voice` : "Stop preview"

  const glyph =
    preview === "rendering" ? (
      <Spinner />
    ) : preview === "playing" ? (
      <StopPreviewIcon />
    ) : (
      <PlayPreviewIcon />
    )

  const toggle = () => setPreview(preview === "idle" ? "rendering" : "idle")

  return (
    <Field data-invalid={overLimit || undefined}>
      <FieldLabel htmlFor={`${fieldId}-response`}>Agent responds</FieldLabel>
      <FieldDescription>
        Saved exactly as typed, diacritics included.
      </FieldDescription>

      <InputGroup>
        <InputGroupInput
          aria-invalid={overLimit}
          dir="auto"
          disabled={disabled}
          id={`${fieldId}-response`}
          onChange={(event) => {
            setPreview("idle")
            onChange(event.target.value)
          }}
          placeholder="What the agent plays back"
          value={value}
        />

        {/* Over the character limit is still worth hearing: the response has
            to be cut down to something, and the reader is choosing which
            words to lose. Only an empty response has nothing to play. */}
        <InputGroupAddon align="inline-end">
          <Tooltip>
            <TooltipTrigger asChild>
              <InputGroupButton
                aria-label={label}
                disabled={!spoken}
                onClick={toggle}
                size="icon-xs"
              >
                {glyph}
              </InputGroupButton>
            </TooltipTrigger>
            {/* The voice is what the preview proves, and it is the one thing
                a triangle cannot say. Parked on the button that plays it
                rather than printed under the field.

                Live even while the field is disabled: hearing the inherited
                acknowledgment is the reason a reader opens the row, and
                playing it changes nothing. */}
            <TooltipContent>{label}</TooltipContent>
          </Tooltip>
        </InputGroupAddon>
      </InputGroup>

      <div className="flex items-baseline justify-end gap-4">
        <span
          className={cn(
            "shrink-0 text-sm tabular-nums",
            overLimit ? "text-destructive" : "text-muted-foreground",
          )}
        >
          {value.length}/{RESPONSE_MAX_CHARS} characters
        </span>
      </div>
    </Field>
  )
}

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { ButtonGroup } from "@/components/ui/button-group"
import { FieldError } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  MAX_TRIGGERS,
  TRIGGER_MAX_CHARS,
  isContested,
  normalize,
  type Conflict,
} from "@/lib/mockups/phrase-mappings-data"
import { cn } from "@/lib/utils"

import { RemoveTriggerIcon } from "./icons"

export function TriggerField({
  conflicts,
  disabled,
  onAdd,
  onRemove,
  triggers,
}: {
  conflicts: Conflict[]
  disabled: boolean
  onAdd: (trigger: string) => void
  onRemove: (trigger: string) => void
  triggers: string[]
}) {
  const [draft, setDraft] = React.useState("")

  const full = triggers.length >= MAX_TRIGGERS
  const tooLong = draft.length > TRIGGER_MAX_CHARS
  const duplicate = triggers.some(
    (trigger) => normalize(trigger) === normalize(draft) && draft.trim() !== "",
  )

  function commit() {
    const value = draft.trim()
    if (!value || full || tooLong || duplicate) return
    onAdd(value)
    setDraft("")
  }

  return (
    <div className="flex flex-col gap-2">
      {/* The chips sit above the field rather than inside it: a phrase here
          can run to a full sentence, which wraps better with the row to
          itself. */}
      {triggers.length ? (
        <div className="flex flex-wrap gap-1.5">
          {triggers.map((trigger) => (
            <Button
              className={cn(
                isContested(trigger, conflicts) &&
                  "bg-destructive/15 text-destructive hover:bg-destructive/25",
              )}
              dir="auto"
              disabled={disabled}
              key={trigger}
              onClick={() => onRemove(trigger)}
              size="xs"
              type="button"
              variant="secondary"
            >
              {trigger}
              <RemoveTriggerIcon data-icon="inline-end" />
            </Button>
          ))}
        </div>
      ) : null}

      {/* Input and Add share an edge instead of the button sitting inside the
          field. Inside, it reads as an ornament on the input; joined, the two
          read as the one control they are — type here, press that. */}
      <ButtonGroup className="w-full">
        <Input
          aria-invalid={tooLong || duplicate}
          dir="auto"
          disabled={disabled || full}
          onBlur={commit}
          onChange={(event) => setDraft(event.target.value)}
          onKeyDown={(event) => {
            if (event.key !== "Enter") return
            event.preventDefault()
            commit()
          }}
          placeholder={
            full
              ? `All ${MAX_TRIGGERS} phrases used`
              : "Add a caller phrase, then press Enter"
          }
          value={draft}
        />

        {/* An explicit Add as well as Enter. Enter alone is invisible, and this
            field is the one place a reader is typing a language the rest of
            the panel is not written in. */}
        <Button
          disabled={disabled || full || !draft.trim() || tooLong || duplicate}
          onClick={commit}
          type="button"
          variant="outline"
        >
          Add
        </Button>
      </ButtonGroup>

      <FieldError>
        {tooLong
          ? `A phrase can be at most ${TRIGGER_MAX_CHARS} characters. This one is ${draft.length}.`
          : duplicate
            ? "This mapping already has that phrase."
            : null}
      </FieldError>
    </div>
  )
}

"use client"

import { HugeiconsIcon, type IconSvgElement } from "@hugeicons/react"

/** No size of its own, so primitives size it through their `[&_svg]:size-4` rules. */
export function icon(glyph: IconSvgElement, displayName: string) {
  const Icon = (
    props: Omit<React.ComponentProps<typeof HugeiconsIcon>, "icon">,
  ) => <HugeiconsIcon icon={glyph} strokeWidth={1.8} {...props} />
  Icon.displayName = displayName
  return Icon
}

