export function personaOverride(globals: FillerConfig): FillerConfig {
  return {
    fillers: [...globals.fillers],
    fillersEnabled: globals.fillersEnabled,
    frequency: globals.frequency,
    mappings: globals.mappings.map((mapping) => ({
      ...mapping,
